import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Development Guidelines","description":"","frontmatter":{"title":"Development Guidelines","order":24},"headers":[],"relativePath":"learn/mod/guidelines.md","filePath":"learn/mod/guidelines.md","lastUpdated":1786957039000}'),i={name:"learn/mod/guidelines.md"};function r(l,e,s,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="development-guidelines" tabindex="-1">Development Guidelines <a class="header-anchor" href="#development-guidelines" aria-label="Permalink to &quot;Development Guidelines&quot;">​</a></h1><p>Before publishing your Mod, please read and follow these guidelines. They protect players, protect developers, and protect the ecosystem.</p><h2 id="_1-don-t-break-original-game-balance" tabindex="-1">1. Don&#39;t Break Original Game Balance <a class="header-anchor" href="#_1-don-t-break-original-game-balance" aria-label="Permalink to &quot;1. Don&#39;t Break Original Game Balance&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Red Line</p><p>Do not create Mods that <strong>break original game balance</strong>, such as modifying judgment, accuracy calculation, damage values, or other content affecting the core game experience. Game judgment is an official red line.</p></div><ul><li>This tutorial <strong>will not</strong> cover how to modify judgment, and you should not promote such features on any channel</li><li>If you want players to get better score displays, refer to the organization&#39;s <a href="./../../mods/not-enough-accuracy">NotEnoughAccuracy</a>, <a href="./../../mods/just-enough-accuracy">JustEnoughAccuracy</a> — accuracy statistics solutions that <strong>don&#39;t affect original judgment</strong></li></ul><h2 id="_2-credit-ai-generated-content" tabindex="-1">2. Credit AI-Generated Content <a class="header-anchor" href="#_2-credit-ai-generated-content" aria-label="Permalink to &quot;2. Credit AI-Generated Content&quot;">​</a></h2><p>If you use AI to generate code, documentation, or assets, note it in the repository.</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- This module was AI-assisted ([tool/model name]), please review manually before use --&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Why:</p><ul><li>Ensures code quality and credibility</li><li>Respects contributors and users</li><li>The organization&#39;s ecosystem values transparency and trust</li></ul><h2 id="_3-don-t-lock-level-content" tabindex="-1">3. Don&#39;t Lock Level Content <a class="header-anchor" href="#_3-don-t-lock-level-content" aria-label="Permalink to &quot;3. Don&#39;t Lock Level Content&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>You must not mark levels or other content as &quot;requires your Mod to open.&quot;</p></div><ul><li>Level files belong to their creators and should not be held hostage by a Mod</li><li>Your Mod can <strong>enhance</strong> the experience, but not <strong>kidnap</strong> content</li><li>Mods published on modrift.org follow the same principle</li></ul><h2 id="_4-don-t-distribute-original-game-binaries" tabindex="-1">4. Don&#39;t Distribute Original Game Binaries <a class="header-anchor" href="#_4-don-t-distribute-original-game-binaries" aria-label="Permalink to &quot;4. Don&#39;t Distribute Original Game Binaries&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Mod artifacts and source repositories <strong>must not contain original game binary files</strong> (<code>Assembly-CSharp.dll</code>, <code>UnityEngine.dll</code>, etc.) — they are copyright-protected.</p></div><ul><li>For original DLLs needed at compile time, use the <strong>private lib repository</strong> approach (see <a href="./github-actions">GitHub Actions Auto Build</a>)</li><li>Build artifacts (Release zips) should only contain your Mod files — don&#39;t include game DLLs</li><li>Decompiling game binaries is for understanding and debugging only — do not distribute</li></ul><h2 id="_5-other-quality-requirements" tabindex="-1">5. Other Quality Requirements <a class="header-anchor" href="#_5-other-quality-requirements" aria-label="Permalink to &quot;5. Other Quality Requirements&quot;">​</a></h2><ul><li><strong>Testing</strong>: features must be tested; verify in a clean environment before publishing</li><li><strong>Comments</strong>: code should have good comments (especially AI-generated parts)</li><li><strong>Data safety</strong>: persisted data should be stored in the Mod&#39;s local config directory to prevent being overwritten on update</li><li><strong>Robustness</strong>: proper error handling — don&#39;t let a single error crash the Mod (see <a href="./harmony-finalizer">Finalizer Patch</a>)</li><li><strong>Collaboration</strong>: if extending an existing Mod&#39;s functionality, prefer submitting a PR to the original project</li></ul><h2 id="what-you-learned" tabindex="-1">What You Learned <a class="header-anchor" href="#what-you-learned" aria-label="Permalink to &quot;What You Learned&quot;">​</a></h2><ul><li>Four uncrossable red lines (balance / credit AI / no content locking / no binaries)</li><li>Basic quality and collaboration requirements</li></ul><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>Running into problems? See <a href="./troubleshooting">Troubleshooting</a></p>',22)])])}const p=t(i,[["render",r]]);export{g as __pageData,p as default};
